// Package types defines the per-agent abstraction interfaces for `entire review`.
//
// AgentReviewer is the contract every supported agent (claude-code, codex,
// gemini, future additions) implements in its own package. The orchestrator
// in cmd/entire/cli/review/run.go consumes this interface, never importing
// concrete agent packages — that's how new agents land as additive files
// without touching shared code.
//
// Events flow as a stream: implementations spawn the agent process, parse
// stdout into a sequence of typed Events (Started, AssistantText, ToolCall,
// Tokens, Finished, RunError), and surface them via Process.Events. Per-agent
// quirks (codex's JSONL envelope shape, gemini's stdin requirement, claude's
// argv shape) are entirely encapsulated inside each agent's adapter — shared
// code only sees the cleaned event stream.
//
// Living in a subpackage (not the review root package) avoids import cycles:
// per-agent reviewers and the orchestrator both depend on these types
// without depending on each other.
package types

import "context"

// AgentReviewer drives a single agent's review run.
type AgentReviewer interface {
	// Name returns the agent's registry key (e.g., "claude-code", "codex",
	// "gemini"). Stable identifier; do not change after release without
	// updating settings migration.
	Name() string

	// Start spawns the agent with the given run configuration. The returned
	// Process exposes streaming events via Events() and a Wait() that returns
	// when the process exits.
	//
	// Implementations MUST set the ENTIRE_REVIEW_* env vars on the spawned
	// child process (see cmd/entire/cli/review/env.go) so the agent's
	// lifecycle hooks adopt the session as a review session.
	//
	// Errors from Start indicate failure to construct or launch the process
	// (e.g., binary not on PATH at exec.Cmd.Start time, invalid argv). Once
	// Start returns nil, errors during the run flow through Process.Events
	// (as RunError) and Process.Wait.
	Start(ctx context.Context, run RunConfig) (Process, error)
}

// Process represents a running agent review.
type Process interface {
	// Events returns a channel that emits structured events as the agent
	// produces output. The channel is closed when the process exits — cleanly,
	// with error, or via context cancellation. Consumers should range over it.
	Events() <-chan Event

	// Wait blocks until the process exits and returns:
	//   - nil on clean exit (exit code 0)
	//   - ctx.Err() on cancellation
	//   - an error wrapping *exec.ExitError on non-zero exit
	//   - other error types for I/O or pipe failures
	//
	// Wait must be called exactly once per Process. It is safe to call Wait
	// after the Events channel has closed. Consumers must drain Events until
	// close before calling Wait; otherwise an implementation that forwards
	// parsed events from another goroutine may block while sending.
	Wait() error
}

// RunConfig is the immutable per-run configuration passed to AgentReviewer.Start.
//
// All fields are optional from a marshalling standpoint (zero value is valid),
// but Skills is typically non-empty in practice — it carries the skill
// invocations (e.g., "/pr-review-toolkit:review-pr") the configured agent
// should run.
type RunConfig struct {
	// PromptOverride, when non-empty, is the exact prompt sent to the agent.
	// It preserves settings.ReviewConfig.Prompt's existing verbatim-override
	// contract: configured skills are still recorded as structured metadata,
	// but they are not prepended to the prompt text.
	PromptOverride string

	// Skills are skill invocation strings passed to the agent verbatim.
	Skills []string

	// AlwaysPrompt is the per-agent always-prompt configured in settings.
	// Concatenated with Skills + PerRunPrompt + a scope clause to form the
	// composed agent prompt.
	AlwaysPrompt string

	// PerRunPrompt is optional textarea input from a single invocation.
	PerRunPrompt string

	// ScopeBaseRef is the git ref the review is scoped against (mainline by
	// default — origin/HEAD → origin/main → origin/master → main → master —
	// or whatever `--base` overrides it to). Used to compose the scope clause
	// and as the base for `git diff` operations the agent may perform.
	ScopeBaseRef string

	// CheckpointContext is best-effort context derived from checkpoints in the
	// branch review scope. It is appended to generated prompts so every agent
	// can use checkpoint IDs, file summaries, and transcript lookup commands
	// while reviewing. PromptOverride remains verbatim and does not receive
	// this context.
	CheckpointContext string

	// StartingSHA is HEAD at invocation time, propagated to the lifecycle
	// hook via ENTIRE_REVIEW_STARTING_SHA so checkpoint metadata records
	// the commit that was reviewed.
	StartingSHA string

	// EnrichSummary optionally updates the completed run summary before sinks
	// receive RunFinished. It is used for post-process data such as token
	// totals that are only available after agent lifecycle hooks flush state.
	//
	// Timing: called on the orchestrator goroutine after every per-agent
	// goroutine has exited, immediately before Sink.RunFinished is fanned
	// out. The full RunSummary is consumed; any field the callback
	// returns reaches the sinks.
	//
	// Contract: nil is valid (no enrichment). The callback must not block on
	// a sink (deadlock), must not panic (no orchestrator-side recovery), and
	// should honor ctx for cancellation when doing I/O.
	EnrichSummary func(context.Context, RunSummary) RunSummary

	// EnrichAgentRun optionally updates a single agent run after that agent
	// exits, before the overall multi-agent run has necessarily completed.
	//
	// Timing: called on the per-agent forwarding goroutine in RunMulti,
	// after proc.Wait() returns and after any synthetic RunError is queued.
	// Only the returned Tokens field is consumed (emitted as a synthetic
	// Tokens event so sinks see live token totals before sibling agents
	// finish); other field changes are discarded. Returning Tokens{In:0,
	// Out:0} suppresses emission entirely.
	//
	// Contract: nil is valid (no enrichment). The callback must be
	// goroutine-safe across N agents and must not block on a sink. A panic
	// is recovered; no synthetic Tokens event is emitted on panic.
	EnrichAgentRun func(context.Context, AgentRun) AgentRun
}

// Event is the sealed sum type emitted by Process.Events. The unexported
// isEvent method prevents external packages from adding event variants;
// adding a new event requires updating this file (and every consumer's
// type switch — that's intentional, since a new event variant is a contract
// change).
type Event interface{ isEvent() }

// Started signals the agent has begun the review. Adapters typically emit
// this once at the top of the event stream.
type Started struct{}

func (Started) isEvent() {}

// AssistantText is narrative output from the agent (the actual review
// response, not tool-call chrome or session metadata).
type AssistantText struct {
	Text string
}

func (AssistantText) isEvent() {}

// ToolCall reports a tool invocation by the agent. Args is an opaque
// adapter-defined string — typically JSON for agents that emit structured
// tool input (e.g., claude-code), or a single-line summary for those that
// don't (e.g., codex). Shared consumers should treat Args as display-only
// and not parse it; structured tool data is intentionally not part of this
// contract.
type ToolCall struct {
	Name string
	Args string
}

func (ToolCall) isEvent() {}

// Tokens reports cumulative token counts (running totals, not deltas).
// Adapters may emit multiple Tokens events during a run; each emission
// supersedes the prior, so consumers should overwrite (not sum) on receipt.
// Adapters that only receive aggregate shutdown totals should emit at most one
// final Tokens event rather than inventing deltas.
type Tokens struct {
	In  int
	Out int
}

func (Tokens) isEvent() {}

// Finished signals the agent has produced its final output and the event
// stream is about to end. Success indicates the agent self-reported a
// clean task completion. Success=false means the agent finished its event
// stream but signaled it did not complete the review task — distinct from
// process exit failure (which surfaces via Process.Wait, not as an event).
//
// Adapters typically emit this once at the bottom of the event stream,
// before the channel closes.
type Finished struct {
	Success bool
}

func (Finished) isEvent() {}

// RunError reports a non-fatal error during the run (e.g., hook failure,
// transient stream parse error). Fatal errors that stop the agent surface
// via Process.Wait, not as events.
type RunError struct {
	Err error
}

func (RunError) isEvent() {}

// Package review — see env.go for package-level rationale.
//
// synthesis_sink.go provides SynthesisSink, an opt-in Sink that prompts the
// user (y/N, default N) after all agents finish, then asks a configured
// summary provider to synthesize a unified verdict across the per-agent
// narratives. Skipped silently in non-TTY mode, on cancellation, or when
// fewer than 2 agents produced usable output.
//
// Composition: appended AFTER DumpSink in TTY-mode sink slices, so the
// y/N prompt appears below the per-agent narrative dump.
package review

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"time"

	"charm.land/huh/v2"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/mdrender"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// SynthesisProvider abstracts the LLM call that produces the cross-agent
// verdict. Injected via Deps so tests can stub the provider call without a
// real API roundtrip. Production wiring (in review_bridge.go) calls into
// the same provider entire explain uses.
type SynthesisProvider interface {
	// Synthesize takes the composed synthesis prompt and returns the
	// verdict text. Errors are surfaced to the caller; SynthesisSink
	// degrades gracefully on error rather than failing the run.
	Synthesize(ctx context.Context, prompt string) (string, error)
}

// SynthesisSink composes a multi-agent verdict by calling a configured
// summary provider after the run finishes. AgentEvent is a no-op; all
// work happens in RunFinished.
type SynthesisSink struct {
	Provider        SynthesisProvider
	Writer          io.Writer
	InputTTY        bool // true if stdin can prompt the user
	PromptYN        func(ctx context.Context, question string, def bool) (bool, error)
	PerRunPrompt    string          // if non-empty, included in the synthesis prompt for context
	RunContext      context.Context // optional; nil falls back to context.Background()
	ProviderTimeout time.Duration   // optional; zero uses defaultSynthesisProviderTimeout
	OnResult        func(result string)
}

// Compile-time interface check.
var _ reviewtypes.Sink = SynthesisSink{}

const defaultSynthesisProviderTimeout = 2 * time.Minute

// AgentEvent is a no-op; SynthesisSink only acts in RunFinished.
func (SynthesisSink) AgentEvent(_ string, _ reviewtypes.Event) {}

// RunFinished optionally synthesizes a cross-agent verdict.
//
// Skip silently when:
//   - stdin isn't a TTY (s.InputTTY == false)
//   - the run was cancelled (summary.Cancelled)
//   - fewer than 2 agents produced usable output (status Succeeded or Failed
//     with non-empty narrative buffer)
//
// Otherwise prompt y/N (default N). On y: compose prompt, call provider,
// print response. On provider failure: print "synthesis unavailable: <err>"
// with the underlying error; user can still commit.
func (s SynthesisSink) RunFinished(summary reviewtypes.RunSummary) {
	if !s.InputTTY {
		return
	}
	if summary.Cancelled {
		return
	}
	if usableAgentCount(summary) < 2 {
		return
	}

	ctx := s.runContext()
	promptFn := s.PromptYN
	if promptFn == nil {
		promptFn = realPromptYN
	}

	yes, err := promptFn(ctx, "Synthesize a unified verdict across all agent reviews?", false)
	if err != nil {
		// huh form errors (terminal-resize anomalies, stdin EOF, stub
		// failures) shouldn't block the user from committing — they get the
		// same silent skip as a "no" answer. Logged at debug for diagnostics.
		logging.Debug(ctx, "synthesis prompt error",
			slog.String("error", err.Error()))
		return
	}
	if !yes {
		return
	}

	synthesisPrompt := composeSynthesisPrompt(summary, s.PerRunPrompt)
	providerCtx, cancelProvider := s.providerContext()
	defer cancelProvider()
	fmt.Fprintln(s.Writer, "Generating summary...")
	result, provErr := s.Provider.Synthesize(providerCtx, synthesisPrompt)
	if provErr != nil {
		fmt.Fprintf(s.Writer, "synthesis unavailable: %v\n", provErr)
		return
	}
	if s.OnResult != nil {
		s.OnResult(result)
	}
	// The synthesis verdict is markdown — render it through the same palette
	// dispatch / DumpSink use, so multi-agent reviews finish with a visually
	// consistent block. Non-TTY writers receive raw markdown unchanged.
	//
	// Use Fprint (not Fprintln): mdrender.Render returns glamour output that
	// already ends with a newline, and the raw-markdown fallback path has its
	// own terminal newline from the LLM response. Adding Fprintln would double
	// the trailing blank line.
	rendered, err := mdrender.RenderForWriter(s.Writer, result)
	if err != nil {
		rendered = result
	}
	fmt.Fprint(s.Writer, rendered)
}

func (s SynthesisSink) runContext() context.Context {
	if s.RunContext != nil {
		return s.RunContext
	}
	return context.Background()
}

func (s SynthesisSink) providerContext() (context.Context, context.CancelFunc) {
	timeout := s.ProviderTimeout
	if timeout <= 0 {
		timeout = defaultSynthesisProviderTimeout
	}
	return context.WithTimeout(s.runContext(), timeout)
}

// usableAgentCount returns the number of agents that produced usable narrative
// output (non-empty AssistantText in their buffer). Used to determine whether
// synthesis is worth offering.
func usableAgentCount(summary reviewtypes.RunSummary) int {
	return len(usableAgentRuns(summary))
}

// realPromptYN is the production y/N prompt using a huh Confirm form.
// Default is false (N). On user cancellation (Ctrl+C) returns false, nil so
// the caller treats it as a "no" answer; on real form errors the error is
// returned so RunFinished can log it via the debug-error path.
func realPromptYN(ctx context.Context, question string, def bool) (bool, error) {
	answer := def
	form := newAccessibleForm(huh.NewGroup(
		huh.NewConfirm().
			Title(question).
			Value(&answer),
	))
	if err := form.RunWithContext(ctx); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
			return false, nil
		}
		return false, fmt.Errorf("synthesis confirm form: %w", err)
	}
	return answer, nil
}

// Package review — see env.go for package-level rationale.
//
// tui_sink.go provides TUISink, a Sink implementation that renders a Bubble
// Tea status dashboard during a review run and supports Ctrl+O
// drill-in mode for inspecting one agent's live event buffer. Used in
// interactive (TTY) runs; non-TTY runs use DumpSink instead.
package review

import (
	"context"
	"io"
	"sync"

	tea "charm.land/bubbletea/v2"
	"golang.org/x/term"

	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// TUISink is a Sink that renders a Bubble Tea dashboard. The orchestrator
// calls AgentEvent/RunFinished from a single goroutine (CU4 serial-dispatch
// contract); the sink translates each event into a tea.Msg and sends it via
// Program.Send. Bubble Tea's Send is thread-safe, but we never rely on that
// property — the serial-dispatch promise means Send is only called from the
// orchestrator's dispatch goroutine.
//
// Cancellation: cancel is the same context.CancelFunc that controls the
// orchestrator's run context. The first KeyCtrlC in the dashboard fires this
// function (guarded by a sync.Once in the model) and switches the dashboard
// to a "Cancelling agents..." indicator while agents drain; a second KeyCtrlC
// force-quits without waiting. Out-of-TUI SIGINT routes through the cobra
// root's context, which cancels the same function — no parallel signal.Notify
// goroutine is needed here.
type TUISink struct {
	program *tea.Program

	mu       sync.Mutex
	started  bool
	finished bool

	done chan struct{} // closed when the tea.Program exits
}

// Compile-time interface check.
var _ reviewtypes.Sink = (*TUISink)(nil)

// NewTUISink creates a TUISink wired to cancel for Ctrl+C handling. agents is
// the ordered list of agent names that will run; the dashboard pre-renders one
// row per agent so the user sees the full run shape from the first frame.
// output is the writer the Bubble Tea program renders into (typically
// cmd.OutOrStdout()). input is the reader Bubble Tea reads keypresses from
// (typically os.Stdin in production); tests must pass a non-TTY reader (e.g.
// bytes.NewReader(nil)) so Bubble Tea does not put the inherited terminal
// into raw mode and corrupt sibling test output.
//
// tea.WithoutSignalHandler keeps SIGINT routing on the cobra root's existing
// handler (which cancels the run context), so the TUI's KeyCtrlC path and the
// OS signal path share a single cancel function with no race.
func NewTUISink(agents []string, cancel context.CancelFunc, output io.Writer, input io.Reader) *TUISink {
	model := newReviewTUIModel(agents, cancel)
	if measureTerminal := terminalMeasurer(output); measureTerminal != nil {
		if width, height, ok := measureTerminal(); ok {
			model.termWidth = width
			model.termHeight = height
		}
	}
	prog := tea.NewProgram(
		model,
		tea.WithOutput(output),
		tea.WithInput(input),
		tea.WithoutSignalHandler(), // SIGINT handled by cobra root; KeyCtrlC calls cancel directly
	)
	return &TUISink{
		program: prog,
		done:    make(chan struct{}),
	}
}

type fdWriter interface {
	Fd() uintptr
}

func terminalMeasurer(output io.Writer) func() (int, int, bool) {
	f, ok := output.(fdWriter)
	if !ok {
		return nil
	}
	return func() (int, int, bool) {
		width, height, err := term.GetSize(int(f.Fd())) //nolint:gosec // fd values fit in int on supported platforms
		if err != nil || width <= 0 || height <= 0 {
			return 0, 0, false
		}
		return width, height, true
	}
}

// Start spawns the Bubble Tea program in its own goroutine. Must be called
// before any AgentEvent calls. Subsequent calls are no-ops.
func (s *TUISink) Start() {
	s.mu.Lock()
	if s.started {
		s.mu.Unlock()
		return
	}
	s.started = true
	s.mu.Unlock()

	go func() {
		defer close(s.done)
		if _, err := s.program.Run(); err != nil {
			// Bubble Tea program errors are non-actionable in a background
			// goroutine (e.g., terminal resize race on exit). Log nothing —
			// the run result is available via RunSummary and the sink's
			// finished state. Swallowing is intentional.
			_ = err
		}
	}()
}

// Wait blocks until the Bubble Tea program exits. Safe to call after Start.
// If Start was never called, Wait returns immediately.
func (s *TUISink) Wait() {
	s.mu.Lock()
	started := s.started
	s.mu.Unlock()
	if !started {
		return
	}
	<-s.done
}

// AgentEvent (Sink interface): translate ev into a tea.Msg and Send it to the
// Bubble Tea program. Implements the serial-dispatch contract: the orchestrator
// calls this from a single goroutine.
//
// Note: Send is safe to call from goroutines other than the TUI's update loop;
// Bubble Tea's implementation queues the message internally.
func (s *TUISink) AgentEvent(agent string, ev reviewtypes.Event) {
	s.mu.Lock()
	ok := s.started && !s.finished
	s.mu.Unlock()
	if !ok {
		return
	}
	s.program.Send(agentEventMsg{agent: agent, ev: ev})
}

// RunFinished (Sink interface): mark the run complete and send the final
// summary message. The TUI shows the dashboard one more frame with the
// terminal statuses, then waits for the user to dismiss it. After a run
// completes, dismissal requires an explicit exit key (q/Esc/Enter/Ctrl+C);
// Ctrl+O still drills into agent buffers for post-mortem inspection. Other
// keys are no-ops so users can navigate the completed run without
// accidentally dismissing.
//
// IMPORTANT: RunFinished blocks until the user dismisses so that post-run
// sinks (e.g. DumpSink) render their narrative AFTER the TUI has exited
// and the terminal is back in normal mode.
func (s *TUISink) RunFinished(summary reviewtypes.RunSummary) {
	s.mu.Lock()
	if s.finished {
		s.mu.Unlock()
		return
	}
	s.finished = true
	s.mu.Unlock()

	s.program.Send(runFinishedMsg{summary: summary})
	// Block until the Bubble Tea program exits — user pressed an explicit
	// exit key (q/Esc/Enter/Ctrl+C) after seeing the final dashboard, or
	// Ctrl+C was received during the run and the program already quit.
	s.Wait()
}

