func newTrailWatchCmd() *cobra.Command {
	var (
		jsonOutput bool
		showPings  bool
		once       bool
	)

	cmd := &cobra.Command{
		Use:   "watch <review-session-id>",
		Short: "Tail a review session's code-review events live",
		Long: `Subscribe to the agent-native code-review SSE stream for a review
session and print events as they arrive. Reconnects automatically when the
server caps the connection (~50s) and on transient network errors.

The review session id is returned by POST /api/v1/review-sessions:start, and
this command streams GET /api/v1/review-sessions/<id>/events.

Events emitted by the server:
  ready              initial frame, includes session/trail and cursor
  <event_type>       code-review domain event (session.started, comment.created, ...)
  reconnect          server cap reached; re-establishing
  session_ended      review session ended; stream ends
  forbidden          access was revoked; stream ends
  error              server-side error; treated as reconnect`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			sessionID := strings.TrimSpace(args[0])
			if sessionID == "" {
				return errors.New("review session id is required")
			}
			return runTrailWatch(cmd, sessionID, jsonOutput, showPings, once)
		},
	}

